    const chars = [];
    for (let i = 0; i < odd; i++) { const c = 2 * r.int(0, big ? 3 : 2) + 1; for (let j = 0; j < c; j++) chars.push(letters[i]); }
    for (let i = 0; i < even; i++) { const c = 2 * r.int(1, big ? 4 : 2); for (let j = 0; j < c; j++) chars.push(letters[odd + i]); }
    while (chars.length < 3) { chars.push(letters[odd + even], letters[odd + even]); }
    return [r.shuffle(chars).join("")];
