function oddMinusEven(s: string): number {
  const cnt = new Map<string, number>();
  for (const ch of s) cnt.set(ch, (cnt.get(ch) ?? 0) + 1);
  let best = -Infinity;
  for (const a of cnt.values())
    for (const b of cnt.values())
      if (a % 2 === 1 && b % 2 === 0) best = Math.max(best, a - b);
  return best;
}

