function oddMinusEven(s: string): number {
  const cnt = new Array(26).fill(0);
  for (let i = 0; i < s.length; i++) cnt[s.charCodeAt(i) - 97]++;
  let maxOdd = -Infinity, minEven = Infinity;
  for (const c of cnt) {
    if (c === 0) continue; // absent letters cannot be picked
    if (c % 2 === 1) maxOdd = Math.max(maxOdd, c);
    else minEven = Math.min(minEven, c);
  }
  return maxOdd - minEven;
}

